-- Awards: an admin-managed catalog of medals and plaques, and the grants that
-- give them to people (todo.md obj. 4.1). Generated by `prisma migrate diff`,
-- then extended with the two invariants below that Prisma cannot express.

-- CreateEnum
CREATE TYPE "AwardKind" AS ENUM ('MEDAL', 'PLAQUE');
-- AlterEnum
ALTER TYPE "NotificationType" ADD VALUE 'AWARD_RECEIVED';
-- CreateTable
CREATE TABLE "Award" (
    "id" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "description" TEXT,
    "kind" "AwardKind" NOT NULL,
    "imageUrl" TEXT NOT NULL,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "createdById" TEXT,
    "archivedAt" TIMESTAMP(3),
    CONSTRAINT "Award_pkey" PRIMARY KEY ("id")
);
-- CreateTable
CREATE TABLE "UserAward" (
    "id" TEXT NOT NULL,
    "userId" TEXT NOT NULL,
    "awardId" TEXT NOT NULL,
    "awardedById" TEXT,
    "awardedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "note" TEXT,
    "pinSlot" INTEGER,
    "displayed" BOOLEAN NOT NULL DEFAULT false,
    CONSTRAINT "UserAward_pkey" PRIMARY KEY ("id")
);
-- CreateIndex
CREATE INDEX "Award_kind_idx" ON "Award"("kind");
-- CreateIndex
CREATE INDEX "UserAward_userId_idx" ON "UserAward"("userId");
-- CreateIndex
