CREATE UNIQUE INDEX "UserAward_userId_pinSlot_key" ON "UserAward"("userId", "pinSlot");
-- AddForeignKey
ALTER TABLE "Award" ADD CONSTRAINT "Award_createdById_fkey" FOREIGN KEY ("createdById") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
-- AddForeignKey
ALTER TABLE "UserAward" ADD CONSTRAINT "UserAward_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
-- AddForeignKey
ALTER TABLE "UserAward" ADD CONSTRAINT "UserAward_awardId_fkey" FOREIGN KEY ("awardId") REFERENCES "Award"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
-- AddForeignKey
ALTER TABLE "UserAward" ADD CONSTRAINT "UserAward_awardedById_fkey" FOREIGN KEY ("awardedById") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;

-- ── Invariants the schema cannot state ─────────────────────────────────────

-- A medal is pinned to slot 1, 2 or 3. The unique (userId, pinSlot) index
-- above stops two medals sharing a slot; this stops a slot 4 existing at all.
ALTER TABLE "UserAward"
  ADD CONSTRAINT "UserAward_pinSlot_range" CHECK ("pinSlot" IS NULL OR "pinSlot" BETWEEN 1 AND 3);

-- At most one plaque displayed under a user's name. A partial unique index,
-- so it holds even if two showcase saves race — the service clears the old
-- flag and sets the new one in a single transaction, and this is the backstop.
CREATE UNIQUE INDEX "UserAward_one_displayed_per_user"
  ON "UserAward"("userId") WHERE "displayed";
